(function(){
const key='almeida-customer-session';let session=null;
const api=(path,opt={})=>fetch(ALMEIDA_SUPABASE_URL+path,{...opt,headers:{apikey:ALMEIDA_SUPABASE_KEY,Authorization:'Bearer '+(session?.access_token||ALMEIDA_SUPABASE_KEY),'Content-Type':'application/json',...(opt.headers||{})}}).then(async r=>{const t=await r.text();let d=t?JSON.parse(t):null;if(!r.ok)throw Error(d?.message||d?.error_description||'Não foi possível concluir.');return d});
function load(){try{session=JSON.parse(localStorage.getItem(key)||'null')}catch{session=null}}
function dialog(){if(document.querySelector('#account-dialog'))return;document.body.insertAdjacentHTML('beforeend',`<dialog id="account-dialog"><button class="close" data-close>×</button><div id="account-view"></div></dialog><dialog id="orders-dialog"><button class="close" data-close>×</button><div id="orders-view"></div></dialog>`);document.querySelectorAll('[data-close]').forEach(b=>b.onclick=()=>b.closest('dialog').close())}
function account(){dialog();const v=document.querySelector('#account-view');if(session){v.innerHTML=`<h2>Minha conta</h2><p>Você está conectado.</p><label class="field">Nome<input id="account-name" value=""></label><label class="field">Telefone<input id="account-phone"></label><label class="field">Endereço padrão<textarea id="account-address" rows="3"></textarea></label><p id="account-balance"></p><button class="primary" id="save-account">Salvar dados</button> <button class="secondary" id="signout">Sair</button>`;api('/auth/v1/user').then(u=>{const p=api('/rest/v1/profiles?select=full_name,phone,default_address&id=eq.'+u.id);return Promise.all([u,p])}).then(([u,p])=>{const x=p?.[0]||{};document.querySelector('#account-name').value=x.full_name||u.user_metadata?.full_name||'';document.querySelector('#account-phone').value=x.phone||'';document.querySelector('#account-address').value=x.default_address?.text||''});api('/rest/v1/wallet_entries?select=entry_type,amount_cents').then(rows=>{const b=rows.reduce((n,x)=>n+(x.entry_type==='credit'?x.amount_cents:-x.amount_cents),0);document.querySelector('#account-balance').textContent='Cashback disponível: '+money(Math.max(0,b))}).catch(()=>{});document.querySelector('#save-account').onclick=async()=>{const u=await api('/auth/v1/user');await api('/rest/v1/profiles?id=eq.'+u.id,{method:'PATCH',headers:{Prefer:'return=minimal'},body:JSON.stringify({full_name:document.querySelector('#account-name').value.trim(),phone:document.querySelector('#account-phone').value.trim(),default_address:{text:document.querySelector('#account-address').value.trim()}})});alert('Dados salvos.')};document.querySelector('#signout').onclick=()=>{session=null;localStorage.removeItem(key);document.querySelector('#account-dialog').close();updateNav()}}
else{v.innerHTML=`<h2>Minha conta</h2><form id="customer-login" class="admin-form"><label>E-mail<input id="customer-email" type="email" required></label><label>Senha<input id="customer-password" type="password" required minlength="6"></label><button class="primary">Entrar</button></form><hr><h3>Criar cadastro</h3><form id="customer-signup" class="admin-form"><label>Nome<input id="customer-name" required></label><label>E-mail<input id="customer-signup-email" type="email" required></label><label>Senha<input id="customer-signup-password" type="password" required minlength="6"></label><button class="secondary">Criar conta</button></form><p id="customer-message" class="admin-message"></p>`;document.querySelector('#customer-login').onsubmit=e=>auth(e,false);document.querySelector('#customer-signup').onsubmit=e=>auth(e,true)}document.querySelector('#account-dialog').showModal()}
async function auth(e,signup){e.preventDefault();const msg=document.querySelector('#customer-message');try{const email=(signup?document.querySelector('#customer-signup-email'):document.querySelector('#customer-email')).value.trim(),password=(signup?document.querySelector('#customer-signup-password'):document.querySelector('#customer-password')).value;const d=await fetch(ALMEIDA_SUPABASE_URL+'/auth/v1/'+(signup?'signup':'token?grant_type=password'),{method:'POST',headers:{apikey:ALMEIDA_SUPABASE_KEY,'Content-Type':'application/json'},body:JSON.stringify(signup?{email,password,data:{full_name:document.querySelector('#customer-name').value.trim()}}:{email,password})}).then(async r=>{const x=await r.json();if(!r.ok)throw Error(x.error_description||x.msg||'E-mail ou senha inválidos.');return x});if(!d.session){msg.textContent='Confira seu e-mail para confirmar o cadastro.';return}session=d.session;localStorage.setItem(key,JSON.stringify(session));document.querySelector('#account-dialog').close();updateNav()}catch(x){msg.textContent=x.message;msg.classList.add('error')}}
function updateNav(){const a=document.querySelector('#account');if(a)a.textContent=session?'Minha conta ✓':'Minha conta'}
async function orders(){dialog();const v=document.querySelector('#orders-view');if(!session){v.innerHTML='<h2>Meus pedidos</h2><p>Entre na sua conta para visualizar seus pedidos.</p>';document.querySelector('#orders-dialog').showModal();return}try{const rows=await api('/rest/v1/orders?select=id,public_number,status,payment_method,amount_due_cents,cashback_reserved_cents,cashback_credited_cents,created_at,order_items(product_name,variant_name,quantity,line_total_cents)&order=created_at.desc');v.innerHTML='<h2>Meus pedidos</h2>'+(rows.length?rows.map(o=>`<article class="order-card"><strong>Pedido #${o.public_number}</strong><span>${o.status==='pending'?'Aguardando confirmação':o.status==='confirmed'?'Confirmado':'Cancelado'}</span><p>${o.order_items.map(i=>`${i.quantity}× ${i.product_name} — ${money(i.line_total_cents)}`).join('<br>')}</p><b>Total: ${money(o.amount_due_cents)}</b></article>`).join(''):'<p>Você ainda não tem pedidos.</p>')}catch(e){v.innerHTML='<p>'+e.message+'</p>'}document.querySelector('#orders-dialog').showModal()}
async function sendOrder(){if(!session){account();return}const payment=$('#payment').value==='cartao'?'card':$('#payment').value==='dinheiro'?'cash':'pix',fulfillment=$('#fulfillment').value==='entrega'?'delivery':'pickup',addr=$('#address')?.value.trim(),requested=Math.max(0,Math.round(Number($('#cashback-use')?.value||0)*100));if(fulfillment==='delivery'&&!addr){$('#address').focus();return}const items=cart.map(i=>({variant_id:produtos[i.id].variacoes[i.vi].id,quantity:i.qty}));if(items.some(i=>!i.variant_id)){alert('Atualize o catálogo antes de finalizar o pedido.');return}const result=await api('/rest/v1/rpc/place_order',{method:'POST',body:JSON.stringify({p_items:items,p_payment_method:payment,p_fulfillment_method:fulfillment,p_delivery_address:addr?{text:addr}:null,p_cashback_requested_cents:requested})});const lines=cart.map(i=>{const p=produtos[i.id],v=p.variacoes[i.vi];return `${i.qty}× ${p.nome} — ${v.nome}`});const msg=`Olá! Pedido #${result.public_number} da Almeida Construções.\n\n${lines.join('\n')}\n\nTotal: ${money(result.amount_due_cents)}\nPagamento: ${payment==='pix'?'PIX':payment==='cash'?'Dinheiro':'Cartão'}\nPedido registrado no site e aguardando confirmação.`;window.open('https://wa.me/553220201300?text='+encodeURIComponent(msg),'_blank','noopener');cart=[];saveCart();$('#cart-dialog').close();alert('Pedido registrado! Você pode acompanhar em Meus pedidos.');}
load();if(document.querySelector('#account')){dialog();document.querySelector('#account').onclick=account;document.querySelector('#orders').onclick=orders;updateNav();}if(typeof send==='function')send=()=>sendOrder();
})();
